{
  "high_level_description": "A Warrior-type MONSTER card artwork showing the following scene: a copper-haired schoolgirl turns sideways in a running leap while firing a heavy shoulder bazooka across a sunlit academy courtyard.",
  "style_description": {
    "aesthetics": "playful anime fantasy character artwork with dynamic airborne action and explosive courtyard details",
    "lighting": "warm daytime sunlight with bright yellow discharge light striking the face, sleeves and metal launcher",
    "medium": "illustration",
    "art_style": "hclar52 card illustration, clean anime digital art with expressive facial anatomy, crisp linework, and painterly environmental backgrounds",
    "color_palette": [
      "#F5E2B3",
      "#2C3446",
      "#D84A46",
      "#E59344",
      "#65768D",
      "#913337"
    ]
  },
  "compositional_deconstruction": {
    "background": "A sunlit academy courtyard with pale stone staircases, fluttering red pennants and blue window shadows. A thick curling discharge cloud passes behind the girl and across the lower foreground, carrying golden sparks and airborne fragments of paving through the warm daylight.",
    "elements": [
      {
        "type": "obj",
        "bbox": [
          12,
          45,
          981,
          936
        ],
        "desc": "A determined schoolgirl with copper twin tails and wide expressive eyes twists sideways in midair. She wears a navy sailor uniform with an ivory collar, red neck ribbon, pleated skirt, opaque tights and buckled boots. Both hands grip a heavy black-and-red bazooka braced against her shoulder, its flared steel muzzle discharging a jagged golden blast."
      }
    ]
  }
}

